+// yamlLocations records the source position of each key and value. CUE's
+// converted YAML positions can be shifted by a column, especially in lists.
+func yamlLocations(file string, b []byte) map[string]fieldLocations {
+	locations := make(map[string]fieldLocations)
+	var root yamlv3.Node
+	if err := yamlv3.Unmarshal(b, &root); err != nil {
+		return locations
+	}
+	var walk func(*yamlv3.Node, []string)
+	walk = func(node *yamlv3.Node, path []string) {
+		switch node.Kind {
+		case yamlv3.DocumentNode:
+			for _, child := range node.Content {
+				walk(child, path)
+			}
+		case yamlv3.MappingNode:
+			for i := 0; i+1 < len(node.Content); i += 2 {
